package com.yeyamo_mobile.api.recommendation_service.application;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.recommendation_service.application.port.*;import com.yeyamo_mobile.api.recommendation_service.domain.Candidate;
@Service public class RecommendationProjectionService{private final RecommendationProjectionPort port;private final RecommendationCachePort cache;public RecommendationProjectionService(RecommendationProjectionPort p,RecommendationCachePort c){port=p;cache=c;}@Transactional public void candidate(Candidate c){port.upsertCandidate(c);cache.invalidate();}@Transactional public void popularity(String source,double delta){port.adjustPopularity(source,delta);cache.invalidate();}@Transactional public void signal(String user,String source,double delta){if(user!=null&&!user.isBlank())port.adjustSignal(user,source,delta);cache.invalidate();}@Transactional public void preference(String user,String region,String language,boolean location){port.updatePreference(user,region,language,location);cache.invalidate();}@Transactional public void countryPreferences(String user,String country,java.util.Set<String> countries,java.util.Set<String> languages){port.updateCountryPreferences(user,country,countries,languages);cache.invalidate();}}
